func copyRandomList(head *Node) *Node {
	if head == nil {
		return nil
	}
	p := head
	// 第一步，在每个原节点后面创建一个新节点
	// 1->1'->2->2'->3->3'
	for p != nil {
		newNode := &Node{Val: p.Val}
		newNode.Next = p.Next
		p.Next = newNode
		p = newNode.Next
	}
	p = head
	// 第二步，设置新节点的随机节点
	for p != nil {
		if p.Random != nil {
			p.Next.Random = p.Random.Next
		}
		p = p.Next.Next
	}
	// 第三步，将两个链表分离
	p = head
	dummy := &Node{Val: -1}
	cur := dummy
	for p != nil {
		cur.Next = p.Next
		cur = cur.Next
		p.Next = cur.Next
		p = p.Next
	}
	return dummy.Next
}

func copyRandomList(head *Node) *Node {
	if head == nil {
		return nil
	}
	// 创建一个哈希表，key 是原节点，value 是新节点
	d := map[*Node]*Node{}
	p := head
	// 将原节点和新节点放入哈希表中
	for p != nil {
		newNode := &Node{Val: p.Val}
		d[p] = newNode
		p = p.Next
	}
	p = head
	// 遍历原链表，设置新节点的 next 和 random
	for p != nil {
		// p 是原节点，d[p] 是对应的新节点，p.Next 是原节点的下一个
		// d[p.Next] 是原节点下一个对应的新节点
		if p.Next != nil {
			d[p].Next = d[p.Next]
		}
		// p.Random 是原节点随机指向，d[p.Random] 是原节点随机指向对应的新节点
		if p.Random != nil {
			d[p].Random = d[p.Random]
		}
		p = p.Next
	}
	// 返回头结点，即原节点对应的 value（新节点）
	return d[head]
}

